using System.Text;

namespace ShaderTool;

/// <summary>Генерирует ShaderCatalog.g.cs: из C# шейдеры берутся по имени, а не по строкам с путями и точками входа.</summary>
public static class CatalogWriter
{
    public static string Generate(ShaderPlan plan)
    {
        var sb = new StringBuilder();
        sb.Append("""
            // <auto-generated>
            // auto-generated by ShaderTool from shaders.json. 
            // </auto-generated>
            #nullable enable

            """);
        sb.Append($"namespace {plan.CatalogNamespace};\n\n");
        sb.Append("""
            /// <param name="Name">debug name.</param>
            /// <param name="Path">Path for ShaderSourceStreamFactory (relative to the application folder).</param>
            /// <param name="Entry">Name of the entry point in HLSL.</param>
            /// <param name="Type">Shader stage.</param>
            /// <param name="Source">Original .slang relative to shaders.json.</param>
            public sealed record ShaderInfo(string Name, string Path, string Entry, global::Diligent.ShaderType Type, string Source);

            public static class ShaderCatalog
            {

            """);

        foreach (var group in plan.Entries.GroupBy(e => e.ClassName))
        {
            sb.Append($"    public static class {group.Key}\n    {{\n");
            foreach (var e in group)
            {
                sb.Append($"        /// <summary>{e.SourceRelative}: {e.Entry} ({e.Stage.ToString().ToLowerInvariant()}) -> {e.RuntimePath}</summary>\n");
                sb.Append($"        public static readonly ShaderInfo {e.MemberName} = new(\n");
                sb.Append($"            {Literal(e.DebugName)}, {Literal(e.RuntimePath)}, {Literal(e.Entry)},\n");
                sb.Append($"            global::Diligent.ShaderType.{e.Stage.DiligentType()}, {Literal(e.SourceRelative)});\n");
            }
            sb.Append("    }\n\n");
        }

        sb.Append("    /// <summary>all shaders.</summary>\n");
        sb.Append("    public static readonly IReadOnlyList<ShaderInfo> All =\n    [\n");
        foreach (var e in plan.Entries)
            sb.Append($"        {e.ClassName}.{e.MemberName},\n");
        sb.Append("    ];\n}\n");

        return sb.ToString();
    }

    /// <summary>Пишет файл, только если содержимое изменилось (чтобы не провоцировать лишнюю пересборку).</summary>
    public static bool WriteIfChanged(string path, string text)
    {
        if (File.Exists(path) && File.ReadAllText(path) == text)
            return false;
        ShaderBuilder.WriteText(path, text);
        return true;
    }

    private static string Literal(string value)
        => "\"" + value.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";
}